const email = items[0].json;

// Extract sender info
const fromHeader = email.payload.headers.find(h => h.name === 'From');
const subjectHeader = email.payload.headers.find(h => h.name === 'Subject');
const dateHeader = email.payload.headers.find(h => h.name === 'Date');

// Extract body text
const getBodyText = (payload) => {
  if (payload.body && payload.body.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }
  if (payload.parts) {
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body && part.body.data) {
        return Buffer.from(part.body.data, 'base64').toString('utf-8');
      }
    }
  }
  return '';
};

const bodyText = getBodyText(email.payload);

return [{
  json: {
    messageId: email.id,
    threadId: email.threadId,
    subject: subjectHeader ? subjectHeader.value : '',
    from: fromHeader ? fromHeader.value : '',
    date: dateHeader ? dateHeader.value : '',
    text: bodyText,
    html: bodyText // Gmail API doesn't separate html/plain easily
  }
}];

const email = items[0].json;

// Parse email from 'Name <email@domain.com>' format
const fromMatch = email.from.match(/([^<]+)<([^>]+)>/);
const senderName = fromMatch ? fromMatch[1].trim() : null;
const senderEmail = fromMatch ? fromMatch[2] : email.from;

return [{
  json: {
    ...email,
    senderName,
    senderEmail
  }
}];

const email = items[0].json;
const llmResponse = items[0].json.response;

try {
  const llm = JSON.parse(llmResponse);
  return [{ json: { email, llm } }];
} catch (e) {
  console.error('Failed to parse LLM response:', e);
  return [{ json: { email, llm: {} } }];
}

